void process_savable_resources(std::vector<GURL>& resources_list, std::vector<Referrer>& referrers_list, std::vector<GURL>& frames_list) {
    // Check if the current wait state is appropriate for processing
    if (!is_ready_to_process()) {
        return;
    }

    // Ensure that the sizes of the resources and referrers lists match
    if (resources_list.size() != referrers_list.size()) {
        return;
    }

    size_t total_items = resources_list.size();
    // Update the download progress if applicable
    update_download_progress(total_items);

    if (total_items == 0) {
        // Treat as user cancellation
        handle_user_cancellation();
        return;
    }

    // Iterate through resources and frames to create SaveItem objects and add to the waiting queue
    for (size_t i = 0; i < total_items; ++i) {
        SaveItem item;
        item.resource_url = resources_list[i];
        item.referrer = referrers_list[i];
        item.frame_url = frames_list[i];
        add_to_waiting_queue(item);
    }

    // Update the wait state
    update_wait_state();

    // Initiate the saving process
    start_saving_process();
}

